19		"github.com/entireio/entire-brain/internal/tui"
20		"github.com/mattn/go-isatty"
21		"github.com/spf13/cobra"
22	)
23	
24	// dashDefaultLimit caps how many entries per tab the dashboard loads. Large
25	// brains can hold thousands of facts/symbols; the cap keeps the snapshot bounded
26	// and a Note records what was dropped so the truncation is never silent. A
27	// non-positive --limit means no cap.
28	const dashDefaultLimit = 500
29	
30	// dashSearchLimit caps results from an in-dashboard search (the `s` key),
31	// matching the `entire brain search` default surface.
32	const dashSearchLimit = 25
33	
34	type dashFlags struct {
35		theme  string
36		tab    string
37		branch string
38		limit  int
39		json   bool
40		plain  bool
41	}
42	
43	func newDashCommand(opts Options) *cobra.Command {
44		var flags dashFlags
45		cmd := &cobra.Command{
46			Use:   "dash [path]",
47			Short: "Browse the brain in an interactive dashboard",
48			Long: `dash opens an interactive terminal dashboard over the brain: a Home tab
49	summarizing source health, freshness, and blind spots, plus explorer tabs that
50	browse individual facts, sessions, history records, and code symbols, each
51	with a detail page. It is read-only and makes no agent calls.
52	
53	On a non-TTY (piped output) it prints a plain summary instead; --json emits the
54	loaded snapshot.`,
55			Args: cobra.MaximumNArgs(1),
56			RunE: func(cmd *cobra.Command, args []string) error {
57				return runDash(cmd.Context(), cmd, opts, flags, agentSurfaceTarget(opts, args))
58			},
59		}
60		cmd.Flags().StringVar(&flags.theme, "theme", "", "Color theme: "+strings.Join(tui.ThemeNames(), ", ")+" (or set ENTIRE_BRAIN_THEME)")
61		cmd.Flags().StringVar(&flags.tab, "tab", "", "Tab to open on: home, facts, sessions, history, semantic, search")
62		cmd.Flags().StringVar(&flags.branch, "branch", "", "Branch whose memories to load (default: current branch)")
63		cmd.Flags().IntVar(&flags.limit, "limit", dashDefaultLimit, "Max entries loaded per tab (0 = no cap)")
64		cmd.Flags().BoolVar(&flags.json, "json", false, "Emit the loaded snapshot as JSON instead of opening the dashboard")
65		cmd.Flags().BoolVar(&flags.plain, "plain", false, "Print a plain text summary instead of opening the dashboard")
66		return cmd
67	}
68	
69	func runDash(ctx context.Context, cmd *cobra.Command, opts Options, flags dashFlags, target string) error {
70		startTab, ok := tui.ParseTab(flags.tab)
71		if !ok && flags.tab != "" {
72			return fmt.Errorf("unknown_tab: %q (want home, facts, sessions, history, semantic, or search)", flags.tab)
73		}
74	
75		// Validate the theme up front (like the tab) so a typo fails fast with the
76		// valid names, in any output mode, rather than silently falling back.
77		theme, err := resolveDashTheme(flags.theme)
78		if err != nil {
79			return err
80		}
81	
82		repoDir, brainDir, branch, err := resolveFactsTarget(ctx, opts, target, flags.branch)
83		if err != nil {
84			return err
85		}
86		privacyPolicy, err := brainstore.CaptureRetrievalPrivacyPolicy(brainDir)
87		if err != nil {
88			return err
89		}
90	
91		snap, err := assembleBrainSnapshot(ctx, opts, target, repoDir, brainDir, branch, flags.limit)
92		if err != nil {
93			return err
94		}
95	
96		// A dumb or unset TERM is a terminal that cannot render escape sequences at
97		// all, so the dashboard must not be started on one: it would arrive as
98		// literal \x1b[?1049h, rounded box-drawing and 256-colour SGR bytes. The
99		// plain summary is the same content in a form that terminal can show, and
100		// the note goes to stderr so stdout stays byte-identical to --plain.
101		dumbTerminal := commandOutputIsTTY(cmd) && !tui.SupportsFullScreen(os.Getenv)
102		if flags.json || flags.plain || !commandOutputIsTTY(cmd) || dumbTerminal {
103			if dumbTerminal && !flags.json && !flags.plain {
104				fmt.Fprintln(cmd.ErrOrStderr(), "note: TERM is unset or dumb — printing the plain summary; the dashboard needs a terminal that renders escape sequences")
105			}
106			return bufferRetrievalCommandOutput(cmd, []retrievalPrivacyPolicy{privacyPolicy}, func() error {
107				if flags.json {
108					return cmdutil.WriteJSON(cmd, snap)
109				}
110				printDashPlain(cmd, snap)
111				return nil
112			})
113		}
114		return tui.Run(snap, theme, brainSearchFunc(repoDir, brainDir, branch), startTab,
115			dashTerminalWriter(cmd.OutOrStdout(), privacyPolicy), brainSourceReader(ctx, opts.Runner, brainDir))
116	}
117	
118	// dashTerminalWriter is the stream the dashboard program renders to: every
119	// write still goes through the privacy re-check, but the terminal underneath
120	// stays visible to the terminal library.
121	//
122	// That second half is not a nicety. bubbletea learns the window size by calling
123	// Fd() on its output and only if the output satisfies term.File (an
124	// io.ReadWriteCloser with an Fd); anything else is "can't query window size",
125	// so it never sends the initial WindowSizeMsg and never installs the SIGWINCH
126	// resize watcher. A plain privacyLinearizedWriter is exactly that anything
127	// else — one Write method — so the dashboard sat on its pre-size placeholder
128	// ("loading…") forever on a real terminal, and resizing it did nothing. It
129	// still accepted keys and still quit on q, which is why exit-code checks never
130	// caught it.
131	//
132	// Embedding the file carries Read/Close/Fd through untouched while Write stays
133	// on the audited path, so the privacy boundary is unchanged.
134	func dashTerminalWriter(out io.Writer, policy retrievalPrivacyPolicy) io.Writer {
135		guarded := privacyLinearizedWriter{out: out, policies: []retrievalPrivacyPolicy{policy}}
136		file, ok := out.(*os.File)
137		if !ok {
138			return guarded
139		}
140		return dashTTYWriter{File: file, guarded: guarded}
141	}
142	
143	// dashTTYWriter is a terminal that writes through the privacy guard. The
144	// embedded *os.File supplies Read/Close/Fd (what bubbletea probes for a window
145	// size); Write is overridden so no byte reaches the terminal unchecked.
146	type dashTTYWriter struct {
147		*os.File
148		guarded privacyLinearizedWriter
149	}
150	
151	func (w dashTTYWriter) Write(p []byte) (int, error) { return w.guarded.Write(p) }
152	
153	// brainSearchFunc adapts the lexical retrieval (`entire brain search`) into the
154	// callback the dashboard's `s` key invokes, so search runs the same code path as
155	// the CLI verb while keeping the TUI free of file IO.
156	func brainSearchFunc(repoDir, brainDir, branch string) tui.SearchFunc {
157		return func(query string) ([]tui.SearchResult, error) {
158			results, err := retrieveUnified(repoDir, brainDir, branch, query, dashSearchLimit, retrieval.ModeLexical)
159			if err != nil {
160				return nil, err
161			}
162			out := make([]tui.SearchResult, 0, len(results))
163			for _, r := range results {
164				out = append(out, searchResultFromUnified(r, brainDir))
165			}
166			return out, nil
167		}
168	}
169	
170	// searchResultFromUnified maps a retrieval hit to the TUI view model and decides
171	// its "open source" target. Only history and doc hits carry a real
172	// brain-relative file path; a fact's Path is its taxonomy labels (not a file),
173	// so a fact hit gets no open target rather than a bogus one.
174	func searchResultFromUnified(r unifiedResult, brainDir string) tui.SearchResult {
175		text := r.Text
176		if r.VerificationRequired {
177			text = "VERIFY AGAINST CURRENT EVIDENCE: " + text
178		}
179		sr := tui.SearchResult{
180			Source:  r.Source,
181			ID:      r.ID,
182			Path:    r.Path,
183			Heading: r.Heading,
184			Line:    r.Line,
185			Text:    text,
186			Score:   r.Score,
187		}
188		if r.Path != "" && (r.Source == "history" || r.Source == "doc") {
189			sr.OpenPath = containedPath(brainDir, r.Path)
190			sr.OpenLine = r.Line
191		}
192		return sr
193	}
194	
195	// assembleBrainSnapshot is the only place that touches the brain on disk. It
196	// reuses the existing loaders to build a read-only tui.Snapshot; no agent calls.
197	func assembleBrainSnapshot(ctx context.Context, opts Options, target, repoDir, brainDir, branch string, limit int) (tui.Snapshot, error) {
198		snap := tui.Snapshot{Repo: repoDir, Branch: branch}
199	
200		status, err := buildBrainStatusReport(ctx, opts, target)
201		if err != nil {
202			return snap, err
203		}
204		if status.Repo.Root != "" {
205			snap.Repo = status.Repo.Root
206		}
207		snap.GeneratedAt = status.Brain.GeneratedAt
208		manifest := status.Manifest
209		guard, err := bmanifest.LoadSessionReadGuard(brainDir, manifest)
210		if err != nil {
211			return snap, err
212		}
213		snap.Home = dashHomeView(status, manifest, branch, guard)
214	
215		// Facts (per branch).
216		if facts, err := factstore.Load(brainDir, branch); err != nil {
217			markSourceUnreadable(&snap.Home, "Facts", "facts unavailable: "+err.Error())
218		} else {
219			facts = factstore.GuardRecords(guard, facts)
220			snap.Facts = dashFactViews(facts, brainDir, limit)
221			snap.Notes = appendCapNote(snap.Notes, "facts", len(facts), len(snap.Facts))
222		}
223	
224		if manifest != nil && manifest.Sources != nil {
225			// Sessions (from the manifest).
226			if s := manifest.Sources.Sessions; s != nil {
227				visibleSessions := bmanifest.GuardSessions(guard, s.Sessions)
228				snap.Sessions = dashSessionViews(visibleSessions, brainDir, limit, guard)
229				snap.Notes = appendCapNote(snap.Notes, "sessions", len(visibleSessions), len(snap.Sessions))
230			}
231			// History (index.json).
232			if h := manifest.Sources.History; h != nil {
233				if idx, err := historystore.LoadIndex(brainDir, h); err != nil {
234					markSourceUnreadable(&snap.Home, "History", "history unavailable: "+err.Error())
235				} else {
236					records := filterHistoryRecords(idx.Records, func(record historyRecord) bool { return !historystore.GuardBlocksRecord(guard, record) })
237					snap.History = dashHistoryViews(records, brainDir, limit)
238					snap.Notes = appendCapNote(snap.Notes, "history", len(records), len(snap.History))
239				}
240			}
241			// Semantic symbols (snapshot.ndjson).
242			if sem := manifest.Sources.Semantic; sem != nil {
243				if syms, err := semstore.LoadSymbols(brainDir, sem, limit); err != nil {
244					markSourceUnreadable(&snap.Home, "Code", "code index unavailable: "+err.Error())
245				} else {
246					snap.Semantic = dashSemanticViews(syms, repoDir)
247					snap.Notes = appendCapNote(snap.Notes, "code symbols", sem.Symbols, len(snap.Semantic))
248				}
249			}
250		}
251	
252		return snap, nil
253	}
254	
255	// markSourceUnreadable records that a source the manifest declares could not
256	// actually be read: the Sources row flips from "present" to "unreadable", its
257	// detail leads with the failure, and the warning is still raised.
258	//
259	// The Sources list is built from the manifest, which only says what the brain
260	// CLAIMS to hold. A corrupt semantic snapshot therefore rendered as "Semantic
261	// present (8 symbols · 18 relations · 2 files)" — manifest counts quoted with
262	// full confidence — directly above a warning that the same file could not be
263	// parsed, and above a tab bar reading "Semantic (0)". Three lines, two of them
264	// true. The row has to carry the bad news itself, because the row is what a
265	// reader scans.
266	func markSourceUnreadable(home *tui.HomeView, name, warning string) {
267		home.Warnings = append(home.Warnings, warning)
268		for i := range home.Sources {
269			if home.Sources[i].Name != name {
270				continue
271			}
272			home.Sources[i].Unreadable = true
273			if claim := home.Sources[i].Detail; claim != "" {
274				home.Sources[i].Detail = warning + " (manifest claims " + claim + ")"
275			} else {
276				home.Sources[i].Detail = warning
277			}
278			return
279		}
280	}
281	
282	// dashHomeView maps the status report into the Home tab view model.
283	func dashHomeView(status brainStatusReport, manifest *exportManifest, branch string, guards ...sessionReadGuard) tui.HomeView {
284		home := tui.HomeView{
285			Freshness:  brainStatusFreshnessSeverity(status),
286			Warnings:   append([]string(nil), status.Warnings...),
287			BlindSpots: dashBlindSpotLabels(brainStatusBlindSpots(status)),
288		}
289	
290		present := status.Sources
291		detail := dashSourceDetails(manifest, guards...)
292		home.Sources = []tui.SourceHealth{
293			{Name: "Seed", Present: present.Seed, Detail: detail["seed"]},
294			{Name: "Sessions", Present: present.Sessions, Detail: detail["sessions"]},
295			{Name: "Code", Present: present.Semantic, Detail: detail["semantic"]},
296			{Name: "History", Present: present.History, Detail: detail["history"]},
297			{Name: "Facts", Present: present.Facts, Detail: detail["facts"]},
298		}
299	
300		if status.Semantic != nil && status.Semantic.Freshness != nil {
301			for name, axis := range status.Semantic.Freshness.Axes {
302				home.Axes = append(home.Axes, tui.FreshnessAxis{Name: name, State: axis.State, Detail: axis.Detail})
303			}
304			sortFreshnessAxes(home.Axes)
305		}
306	
307		home.Live = tui.LiveState{
308			Branch:  clibase.FirstNonEmpty(status.Live.Branch, branch),
309			Head:    status.Live.Head,
310			Dirty:   status.Live.Dirty,
311			Summary: dashLiveSummary(status.Live),
312		}
313	
314		if manifest != nil && manifest.GeneratedAt.IsZero() && !anySource(present) {
315			home.Warnings = append(home.Warnings, "brain not built yet — run `"+clibase.BrainInvocation(os.LookupEnv, "refresh")+"`")
316		}
317		return home
318	}
319	
320	func dashSourceDetails(manifest *exportManifest, guards ...sessionReadGuard) map[string]string {
321		out := map[string]string{}
322		if manifest == nil || manifest.Sources == nil {
323			return out
324		}
325		src := manifest.Sources
326		if s := src.Sessions; s != nil {
327			count, checkpoints := len(s.Sessions), s.CheckpointsScanned
328			if len(guards) > 0 && !guards[0].Empty() {
329				visible := bmanifest.GuardSessions(guards[0], s.Sessions)
330				count, checkpoints = len(visible), 0
331				for _, session := range visible {
332					checkpoints += session.CheckpointsCount
333				}
334			}
335			out["sessions"] = fmt.Sprintf("%d sessions · %d checkpoints scanned", count, checkpoints)
336		}
337		if s := src.Semantic; s != nil {
