565	func commandOutputIsTTY(cmd *cobra.Command) bool {
566		if f, ok := cmd.OutOrStdout().(*os.File); ok {
567			return isatty.IsTerminal(f.Fd()) || isatty.IsCygwinTerminal(f.Fd())
568		}
569		return false
