623	// brainSourceReader keeps virtual transcript addresses out of the OS opener.
624	// Reads happen only on demand and use the same fresh privacy gate as retrieval;
625	// the TUI holds bytes in memory and never leaves temporary transcript files.
626	func brainSourceReader(ctx context.Context, runner CommandRunner, brainDir string) tui.SourceReader {
627		store := newTranscriptStore(runner, brainDir)
628		return func(target string) (string, bool, error) {
629			rel, err := filepath.Rel(brainDir, target)
630			if err != nil {
631				return "", false, nil
632			}
633			rel = filepath.ToSlash(rel)
634			if !strings.HasPrefix(rel, "sessions/") {
635				return "", false, nil
636			}
637			data, err := store.Read(ctx, rel)
638			return string(data), true, err
639		}
640	}
