24	// dashDefaultLimit caps how many entries per tab the dashboard loads. Large
25	// brains can hold thousands of facts/symbols; the cap keeps the snapshot bounded
26	// and a Note records what was dropped so the truncation is never silent. A
27	// non-positive --limit means no cap.
28	const dashDefaultLimit = 500
29	
30	// dashSearchLimit caps results from an in-dashboard search (the `s` key),
31	// matching the `entire brain search` default surface.
32	const dashSearchLimit = 25
33	
34	type dashFlags struct {
35		theme  string
36		tab    string
37		branch string
38		limit  int
39		json   bool
40		plain  bool
41	}
