352	func dashBlindSpotLabels(spots []brainBlindSpot) []string {
353		if len(spots) == 0 {
354			return nil
355		}
356		out := make([]string, 0, len(spots))
357		for _, s := range spots {
358			label := s.Detail
359			if label == "" {
360				label = s.Code
361			}
362			if s.Path != "" {
363				if label == "" {
364					label = s.Path
365				} else {
366					label = s.Path + ": " + label
367				}
368			}
369			if label == "" {
370				continue
371			}
372			out = append(out, label)
373		}
374		return out
375	}
