377	func dashLiveSummary(live brainLiveState) string {
378		if !live.Dirty {
379			return "clean"
380		}
381		parts := make([]string, 0, 3)
382		if n := len(live.Staged); n > 0 {
383			parts = append(parts, fmt.Sprintf("%d staged", n))
384		}
385		if n := len(live.Unstaged); n > 0 {
386			parts = append(parts, fmt.Sprintf("%d unstaged", n))
387		}
388		if n := len(live.Untracked); n > 0 {
389			parts = append(parts, fmt.Sprintf("%d untracked", n))
390		}
391		if len(parts) == 0 {
392			return "dirty"
393		}
394		return strings.Join(parts, " · ")
395	}
