397	func dashFactViews(facts []factRecord, brainDir string, limit int) []tui.FactView {
398		if limit > 0 && len(facts) > limit {
399			facts = facts[:limit]
400		}
401		out := make([]tui.FactView, 0, len(facts))
402		for _, f := range facts {
403			view := tui.FactView{
404				ID:         f.ID,
405				Kind:       f.Kind,
406				Text:       f.Text,
407				Paths:      f.Paths,
408				Locus:      f.Locus,
409				Status:     f.Status,
410				Origin:     f.Origin,
411				Confidence: f.Confidence,
412				Related:    f.RelatedIDs,
413			}
414			for _, a := range f.Provenance {
415				view.Provenance = append(view.Provenance, tui.Anchor{
416					SessionID:  a.SessionID,
417					Commit:     a.Commit,
418					Transcript: a.Transcript,
419					Line:       a.Line,
420					Verified:   a.Verified,
421				})
422			}
423			if len(f.Provenance) > 0 && f.Provenance[0].Transcript != "" {
424				view.Source = containedPath(brainDir, f.Provenance[0].Transcript)
425				view.SourceLine = f.Provenance[0].Line
426			}
427			out = append(out, view)
428		}
429		return out
430	}
