516	// printDashPlain renders the snapshot as plain text for non-TTY / --plain use,
517	// reusing the brain summary shape.
518	func printDashPlain(cmd *cobra.Command, snap tui.Snapshot) {
519		out := cmd.OutOrStdout()
520		fmt.Fprintf(out, "Brain dashboard — %s (branch %s)\n", orEmpty(snap.Repo), orEmpty(snap.Branch))
521		if snap.GeneratedAt != "" {
522			fmt.Fprintf(out, "built: %s\n", snap.GeneratedAt)
523		}
524		fmt.Fprintln(out, "\nSources")
525		for _, s := range snap.Home.Sources {
526			line := fmt.Sprintf("  %-9s %s", s.Name, s.State())
527			if s.Detail != "" {
528				line += "  (" + s.Detail + ")"
529			}
530			fmt.Fprintln(out, line)
531		}
532		if snap.Home.Freshness != "" {
533			fmt.Fprintf(out, "freshness: %s\n", snap.Home.Freshness)
534		}
535		fmt.Fprintf(out, "\nFacts (%d) · Sessions (%d) · History (%d) · Code (%d)\n",
536			len(snap.Facts), len(snap.Sessions), len(snap.History), len(snap.Semantic))
537		for _, bs := range snap.Home.BlindSpots {
538			fmt.Fprintf(out, "  blind spot: %s\n", bs)
539		}
540		for _, w := range snap.Home.Warnings {
541			fmt.Fprintf(out, "  warning: %s\n", w)
542		}
543		for _, n := range snap.Notes {
544			fmt.Fprintf(out, "  note: %s\n", n)
545		}
546	}
