548	// resolveDashTheme picks the theme from the --theme flag, falling back to
549	// ENTIRE_BRAIN_THEME, then the default scheme. A non-empty name that matches no
550	// known theme is an error (so a typo is surfaced, not silently ignored); an
551	// empty name resolves to the default without error.
552	func resolveDashTheme(flagValue string) (tui.Theme, error) {
553		name := flagValue
554		if name == "" {
555			name = os.Getenv("ENTIRE_BRAIN_THEME")
556		}
557		theme, ok := tui.ThemeByName(name)
558		if !ok && name != "" {
559			return theme, fmt.Errorf("unknown_theme: %q (want %s)", name, strings.Join(tui.ThemeNames(), ", "))
560		}
561		return theme, nil
562	}
