572	// --- small helpers ---------------------------------------------------------
573	
574	// containedPath joins a relative path to a base dir, returning "" for an empty,
575	// absolute, rooted, or escaping path. Path values come straight out of on-disk
576	// brain/snapshot files, so a "../"-laden or rooted value must never resolve to an
577	// open target outside the base (the `o` key hands the result to the OS opener).
578	func containedPath(base, rel string) string {
579		// Reject absolute and rooted paths. filepath.IsAbs is OS-specific (on Windows
580		// a leading-slash path like "/etc/passwd" is NOT absolute), so also reject a
581		// leading "/" or "\" explicitly — a rooted path is never a valid relative
582		// anchor on any platform.
583		if rel == "" || filepath.IsAbs(rel) || strings.HasPrefix(rel, "/") || strings.HasPrefix(rel, `\`) {
584			return ""
585		}
586		clean := filepath.Clean(filepath.FromSlash(rel))
587		if clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
588			return ""
589		}
590		full := filepath.Join(base, clean)
591		if r, err := filepath.Rel(base, full); err != nil || r == ".." || strings.HasPrefix(r, ".."+string(filepath.Separator)) {
592			return ""
593		}
594		return full
595	}
