334	// boundedRetrievalJSONPayload removes optional extras, then whole tail rows,
335	// until the exact serialization fits. The response_truncated marker is
336	// present during every truncated size check, so the marker itself can never
337	// push the emitted document over budget.
338	func boundedRetrievalJSONPayload(query, branch string, results []unifiedResult, extras retrievalTransportExtras) (map[string]any, error) {
339		allRows := compactUnifiedResults(results, query)
340		extras = cloneRetrievalTransportExtras(extras)
341		extrasSteps := countRetrievalExtrasTrims(extras)
342		build := func(steps int) map[string]any {
343			ex := cloneRetrievalTransportExtras(extras)
344			for i := 0; i < min(steps, extrasSteps); i++ {
345				trimRetrievalExtrasOnce(&ex)
346			}
347			rows := append([]compactUnifiedResult{}, allRows[:len(allRows)-max(steps-extrasSteps, 0)]...)
348			return buildRetrievalJSONPayload(query, branch, rows, ex, steps > 0)
349		}
350		sizeAt := func(steps int) (int, error) {
351			data, err := jsonOutputBytes(build(steps))
352			if err != nil {
353				return 0, err
354			}
355			return len(data), nil
356		}
357		if size, err := sizeAt(0); err != nil {
358			return nil, err
359		} else if size <= conversationConceptResponseMaxBytes {
360			return build(0), nil
361		}
362		steps, ok, err := smallestTrimStepsThatFit(extrasSteps+len(allRows), sizeAt)
363		if err != nil {
364			return nil, err
365		}
366		if !ok {
367			return nil, fmt.Errorf("retrieval response envelope exceeds %d bytes without any result rows", conversationConceptResponseMaxBytes)
368		}
369		return build(steps), nil
370	}
