496	func qualifyAbstractStatement(repoKey, workspaceName string, statement abstractStatement) abstractStatement {
497		statement.EvidenceIDs = append([]string(nil), statement.EvidenceIDs...)
498		for i := range statement.EvidenceIDs {
499			statement.EvidenceIDs[i] = qualifyWorkspaceAddressableID(repoKey, workspaceName, statement.EvidenceIDs[i])
500		}
501		return statement
