560	func qualifyWorkspaceRetrieveGroups(workspaceName string, groups []workspaceRetrieveResult) []workspaceRetrieveResult {
561		out := make([]workspaceRetrieveResult, len(groups))
562		for i, group := range groups {
563			out[i] = group
564			out[i].Results = make([]unifiedResult, len(group.Results))
565			for j, result := range group.Results {
566				out[i].Results[j] = qualifyWorkspaceUnifiedResult(group.RepoKey, workspaceName, result)
567			}
568			out[i].AbstractPreviews = make([]sessionAbstractPreview, len(group.AbstractPreviews))
569			for j, preview := range group.AbstractPreviews {
570				out[i].AbstractPreviews[j] = qualifyWorkspacePreview(group.RepoKey, workspaceName, preview)
571			}
572		}
573		return out
574	}
