609	func cloneWorkspaceRetrieveGroups(groups []workspaceRetrieveResult) []workspaceRetrieveResult {
610		out := make([]workspaceRetrieveResult, len(groups))
611		for i, group := range groups {
612			out[i] = group
613			out[i].Results = append([]unifiedResult(nil), group.Results...)
614			out[i].AbstractPreviews = append([]sessionAbstractPreview(nil), group.AbstractPreviews...)
615		}
616		return out
617	}
