619	// trimWorkspaceExtrasOnce drops one lowest-priority optional tail item so the
620	// caller keeps a useful bounded response. A member's Error is deliberately NOT
621	// trimmable: clearing it makes a member whose retrieval failed serialize as
622	// {"results": []}, byte-identical to a healthy member with no matches, and the
623	// generic response_truncated marker does not say a failure was suppressed.
624	// Ranked rows are the cheap thing to drop; a member's failure is not.
625	func trimWorkspaceExtrasOnce(groups []workspaceRetrieveResult) bool {
626		for i := len(groups) - 1; i >= 0; i-- {
627			switch {
628			case len(groups[i].AbstractPreviews) > 0:
629				groups[i].AbstractPreviews = groups[i].AbstractPreviews[:len(groups[i].AbstractPreviews)-1]
630				groups[i].AbstractPreviewsTruncated = true
631				return true
632			case groups[i].Freshness.Detail != "":
633				groups[i].Freshness.Detail = ""
634				return true
635			case groups[i].Freshness.ContractDetail != "":
636				groups[i].Freshness.ContractDetail = ""
637				return true
638			}
639		}
640		return false
641	}
642	
643	// countWorkspaceExtrasTrims reports how many steps trimWorkspaceExtrasOnce
644	// can apply to groups before it is exhausted.
645	func countWorkspaceExtrasTrims(groups []workspaceRetrieveResult) int {
646		gs := cloneWorkspaceRetrieveGroups(groups)
647		n := 0
648		for trimWorkspaceExtrasOnce(gs) {
649			n++
650		}
651		return n
652	}
653	
654	// applyWorkspaceTrimSteps rebuilds the trim state after `steps` steps of the
655	// deterministic sequence shared by both workspace surfaces: optional extras
656	// first, then one kept row at a time, then whole tail groups.
657	func applyWorkspaceTrimSteps(pristine []workspaceRetrieveResult, extrasSteps, total, steps int) (groups []workspaceRetrieveResult, keep int) {
658		gs := cloneWorkspaceRetrieveGroups(pristine)
659		for i := 0; i < min(steps, extrasSteps); i++ {
660			trimWorkspaceExtrasOnce(gs)
661		}
662		rowDrops := min(max(steps-extrasSteps, 0), total)
663		groupDrops := max(steps-extrasSteps-total, 0)
664		return gs[:len(gs)-groupDrops], total - rowDrops
665	}
666	
667	func boundedWorkspaceRetrievalJSONPayload(workspaceName, query string, groups []workspaceRetrieveResult) (map[string]any, error) {
668		qualified := cloneWorkspaceRetrieveGroups(qualifyWorkspaceRetrieveGroups(workspaceName, groups))
669		total := 0
670		for _, group := range qualified {
671			total += len(group.Results)
672		}
673		extrasSteps := countWorkspaceExtrasTrims(qualified)
674		build := func(steps int) map[string]any {
675			gs, keep := applyWorkspaceTrimSteps(qualified, extrasSteps, total, steps)
676			payload := map[string]any{
677				"workspace": workspaceName,
678				"query":     query,
679				"results":   trimWorkspaceGroupsToCount(gs, keep, steps > 0),
680			}
681			if steps > 0 {
682				payload["response_truncated"] = true
683			}
684			return payload
685		}
686		sizeAt := func(steps int) (int, error) {
687			data, err := jsonOutputBytes(build(steps))
688			if err != nil {
689				return 0, err
690			}
691			return len(data), nil
692		}
693		if size, err := sizeAt(0); err != nil {
694			return nil, err
695		} else if size <= conversationConceptResponseMaxBytes {
696			return build(0), nil
697		}
698		steps, ok, err := smallestTrimStepsThatFit(extrasSteps+total+len(qualified), sizeAt)
699		if err != nil {
700			return nil, err
701		}
702		if !ok {
703			return nil, fmt.Errorf("workspace retrieval response envelope exceeds %d bytes without any result rows", conversationConceptResponseMaxBytes)
704		}
705		return build(steps), nil
706	}
707	
708	func renderWorkspaceRetrievalText(workspaceName string, groups []workspaceRetrieveResult, keep int, truncated bool) []byte {
709		var out bytes.Buffer
710		remaining := keep
711		for _, group := range groups {
712			count := min(remaining, len(group.Results))
713			remaining -= count
714			qualify := func(id string) string { return qualifyWorkspaceAddressableID(group.RepoKey, workspaceName, id) }
715			renderRetrievalRowsText(&out, group.Results[:count], qualify)
716			if group.Error != "" {
717				fmt.Fprintf(&out, "%s error %s\n", group.RepoKey, group.Error)
718			}
719		}
720		fmt.Fprintf(&out, "response_truncated %t\n", truncated)
721		return out.Bytes()
722	}
723	
724	func boundedWorkspaceRetrievalText(workspaceName string, groups []workspaceRetrieveResult) ([]byte, error) {
725		groups = cloneWorkspaceRetrieveGroups(groups)
726		total := 0
727		for _, group := range groups {
728			total += len(group.Results)
729		}
730		extrasSteps := countWorkspaceExtrasTrims(groups)
731		render := func(steps int) []byte {
732			gs, keep := applyWorkspaceTrimSteps(groups, extrasSteps, total, steps)
733			return renderWorkspaceRetrievalText(workspaceName, gs, keep, steps > 0)
734		}
735		if data := render(0); len(data) <= conversationConceptResponseMaxBytes {
736			return data, nil
737		}
738		steps, ok, err := smallestTrimStepsThatFit(extrasSteps+total+len(groups), func(steps int) (int, error) {
739			return len(render(steps)), nil
740		})
741		if err != nil {
742			return nil, err
743		}
744		if !ok {
745			return nil, fmt.Errorf("workspace retrieval text envelope exceeds %d bytes without any result rows", conversationConceptResponseMaxBytes)
746		}
747		return render(steps), nil
748	}
