29	// beforeRetrievalResponsePrivacyRecheck is a deterministic race seam for
30	// tests. Production leaves it as a no-op. It runs after ranking and immediately
31	// before the authoritative pre-emission privacy check.
32	var beforeRetrievalResponsePrivacyRecheck = func() {}
33	
34	// beforeRetrievalResponsePrivacyEmissionCheck is the final transport-boundary
35	// race seam. Production leaves it as a no-op; tests use it to land a tombstone
36	// after the complete response has been buffered but before any byte is written.
37	var beforeRetrievalResponsePrivacyEmissionCheck = func() {}
38	
39	// beforeRetrievalResponseWrite is a deterministic seam after the authoritative
40	// policy checks have succeeded but while every involved Brain write lock is
41	// still held. Tests use it to prove a concurrent tombstone writer cannot
42	// linearize between the last privacy check and the first response byte.
43	var beforeRetrievalResponseWrite = func() {}
44	
45	// The retrieval privacy policy lives in brainstore; the alias keeps the
46	// package-local name for the many existing readers and tests.
47	type retrievalPrivacyPolicy = brainstore.RetrievalPrivacyPolicy
48	
49	// bufferRetrievalCommandOutput preserves each command's exact legacy bytes
50	// while moving the authoritative privacy check to one shared final boundary.
51	// Rendering failures discard the private buffer and emit nothing.
52	func bufferRetrievalCommandOutput(cmd *cobra.Command, policies []retrievalPrivacyPolicy, render func() error) error {
53		original := cmd.OutOrStdout()
54		var buffered bytes.Buffer
55		cmd.SetOut(&buffered)
56		defer cmd.SetOut(original)
57		if err := render(); err != nil {
58			return err
59		}
60		cmd.SetOut(original)
61		return writeRetrievalResponseBytes(original, buffered.Bytes(), policies...)
62	}
63	
64	// privacyLinearizedWriter is for an interactive surface that cannot buffer its
65	// entire lifetime (the dashboard TUI). Each terminal write is linearized under
66	// the captured policy; once policy changes, the next draw fails closed.
67	type privacyLinearizedWriter struct {
68		out      io.Writer
69		policies []retrievalPrivacyPolicy
70	}
71	
72	func (w privacyLinearizedWriter) Write(p []byte) (int, error) {
73		err := writeRetrievalResponseBytes(w.out, p, w.policies...)
74		if err != nil {
75			return 0, err
76		}
77		return len(p), nil
78	}
79	
80	// writeRetrievalResponseBytes is the only final write boundary for retrieval,
81	// get, brief, and workspace payloads. Callers must buffer the exact response
82	// first. A policy change never produces a partial stale response: every checked
83	// brain is revalidated before the first byte is handed to the consumer.
84	func writeRetrievalResponseBytes(out io.Writer, data []byte, policies ...retrievalPrivacyPolicy) error {
85		beforeRetrievalResponsePrivacyEmissionCheck()
86		if transactional, ok := out.(interface {
87			writeRetrievalResponse([]byte, []retrievalPrivacyPolicy) error
88		}); ok {
89			return transactional.writeRetrievalResponse(data, policies)
90		}
91		return withLockedRetrievalPrivacyPolicies(policies, func() error {
92			beforeRetrievalResponseWrite()
93			n, err := out.Write(data)
94			if err == nil && n != len(data) {
95				return io.ErrShortWrite
96			}
97			return err
98		})
99	}
100	
101	// withLockedRetrievalPrivacyPolicies is the response linearization boundary
102	// (brainstore owns the lock ordering and identity revalidation); the CLI
103	// adapters bind the derived-read gate.
104	func withLockedRetrievalPrivacyPolicies(policies []retrievalPrivacyPolicy, fn func() error) error {
105		return brainstore.WithLockedRetrievalPrivacyPolicies(policies, requirePrivacyDerivedRead, fn)
106	}
107	
108	func acquireRetrievalPrivacyPolicies(policies []retrievalPrivacyPolicy) (func(), error) {
109		return brainstore.AcquireRetrievalPrivacyPolicies(policies, requirePrivacyDerivedRead)
110	}
111	
112	// commitVizRetrievalResponse is the viz HTTP transport's final privacy
113	// boundary: it binds the cli race seams and the locked-policy write around the
114	// buffered response commit (injected as viz.Deps.CommitRetrievalResponse).
115	func commitVizRetrievalResponse(policies []retrievalPrivacyPolicy, write func() error) error {
116		beforeRetrievalResponsePrivacyEmissionCheck()
117		return withLockedRetrievalPrivacyPolicies(policies, func() error {
118			beforeRetrievalResponseWrite()
119			return write()
120		})
121	}
