207	func filterAbstractPreviewsForRows(previews []sessionAbstractPreview, rows []compactUnifiedResult) ([]sessionAbstractPreview, bool) {
208		if len(previews) == 0 {
209			return nil, false
210		}
211		refs := make(map[string]bool, len(rows))
212		for _, row := range rows {
213			if row.SessionRef != "" {
214				refs[row.SessionRef] = true
215			}
216		}
217		out := make([]sessionAbstractPreview, 0, len(previews))
218		for _, preview := range previews {
219			if refs[preview.SessionRef] {
220				out = append(out, preview)
221			}
222		}
223		return out, len(out) != len(previews)
224	}
