226	func buildRetrievalJSONPayload(query, branch string, rows []compactUnifiedResult, extras retrievalTransportExtras, truncated bool) map[string]any {
227		payload := map[string]any{"query": query, "branch": branch, "results": rows}
228		if truncated {
229			payload["response_truncated"] = true
230			if len(rows) > 0 {
231				// Preserve the additive row marker shipped by the initial multi-concept surface,
232				// while making the envelope marker usable even when zero rows fit.
233				rows[len(rows)-1].ResponseTruncated = true
234				payload["results"] = rows
235			}
236		}
237		if previews, cut := filterAbstractPreviewsForRows(extras.AbstractPreviews, rows); len(previews) > 0 || extras.AbstractPreviews != nil {
238			payload["abstract_previews"] = previews
239			payload["abstract_previews_truncated"] = extras.AbstractPreviewsTruncated || cut
240		}
241		if len(extras.Hints.LikelyEditFiles) > 0 {
242			payload["likely_edit_files"] = extras.Hints.LikelyEditFiles
243		}
244		if len(extras.Hints.LikelyTestFiles) > 0 {
245			payload["likely_test_files"] = extras.Hints.LikelyTestFiles
246		}
247		if len(extras.Hints.ActionChecklist) > 0 {
248			payload["action_checklist"] = extras.Hints.ActionChecklist
249		}
250		if len(extras.Related) > 0 {
251			payload["related_patterns"] = extras.Related
252		}
253		if len(rows) == 0 && extras.BlindSpot != "" {
254			payload["blind_spot"] = extras.BlindSpot
255		}
256		return payload
257	}
