268	// trimRetrievalExtrasOnce drops one lowest-priority optional tail item. This
269	// gives the caller a useful bounded response even when previews or discovery
270	// pointers consume the budget before any ranked row does.
271	func trimRetrievalExtrasOnce(extras *retrievalTransportExtras) bool {
272		switch {
273		case len(extras.AbstractPreviews) > 0:
274			extras.AbstractPreviews = extras.AbstractPreviews[:len(extras.AbstractPreviews)-1]
275			extras.AbstractPreviewsTruncated = true
276		case len(extras.Related) > 0:
277			extras.Related = extras.Related[:len(extras.Related)-1]
278		case len(extras.Hints.ActionChecklist) > 0:
279			extras.Hints.ActionChecklist = extras.Hints.ActionChecklist[:len(extras.Hints.ActionChecklist)-1]
280		case len(extras.Hints.LikelyTestFiles) > 0:
281			extras.Hints.LikelyTestFiles = extras.Hints.LikelyTestFiles[:len(extras.Hints.LikelyTestFiles)-1]
282		case len(extras.Hints.LikelyEditFiles) > 0:
283			extras.Hints.LikelyEditFiles = extras.Hints.LikelyEditFiles[:len(extras.Hints.LikelyEditFiles)-1]
284		case extras.BlindSpot != "":
285			extras.BlindSpot = ""
286		default:
287			return false
288		}
289		return true
290	}
