303	// smallestTrimStepsThatFit finds the fewest trim steps, between 1 and
304	// maxSteps, whose rendering fits the response budget. Trimming is monotone —
305	// every step only removes content — so once some step count fits, every
306	// larger one fits, and a binary search returns the same state the former
307	// one-step-at-a-time loop reached while rendering O(log n) candidates
308	// instead of O(n). sizeAt must rebuild from pristine inputs so probes are
309	// order-independent. The untrimmed rendering is the caller's job to check
310	// first: step one adds the truncation marker and can grow the output.
311	func smallestTrimStepsThatFit(maxSteps int, sizeAt func(int) (int, error)) (int, bool, error) {
312		if maxSteps < 1 {
313			return 0, false, nil
314		}
315		if size, err := sizeAt(maxSteps); err != nil || size > conversationConceptResponseMaxBytes {
316			return 0, false, err
317		}
318		lo, hi := 1, maxSteps
319		for lo < hi {
320			mid := (lo + hi) / 2
321			size, err := sizeAt(mid)
322			if err != nil {
323				return 0, false, err
324			}
325			if size <= conversationConceptResponseMaxBytes {
326				hi = mid
327			} else {
328				lo = mid + 1
329			}
330		}
331		return lo, true, nil
332	}
