576	func trimWorkspaceGroupsToCount(groups []workspaceRetrieveResult, keep int, truncated bool) []workspaceRetrieveResult {
577		out := make([]workspaceRetrieveResult, len(groups))
578		remaining := keep
579		lastGroup, lastRow := -1, -1
580		for i, group := range groups {
581			out[i] = group
582			count := min(remaining, len(group.Results))
583			out[i].Results = append([]unifiedResult(nil), group.Results[:count]...)
584			remaining -= count
585			if count > 0 {
586				lastGroup, lastRow = i, count-1
587			}
588			refs := map[string]bool{}
589			for _, result := range out[i].Results {
590				if result.SessionRef != "" {
591					refs[result.SessionRef] = true
592				}
593			}
594			previews := make([]sessionAbstractPreview, 0, len(group.AbstractPreviews))
595			for _, preview := range group.AbstractPreviews {
596				if refs[preview.SessionRef] {
597					previews = append(previews, preview)
598				}
599			}
600			out[i].AbstractPreviews = previews
601			out[i].AbstractPreviewsTruncated = group.AbstractPreviewsTruncated || len(previews) != len(group.AbstractPreviews)
602		}
603		if truncated && lastGroup >= 0 {
604			out[lastGroup].Results[lastRow].ResponseTruncated = true
605		}
606		return out
