619	// trimWorkspaceExtrasOnce drops one lowest-priority optional tail item so the
620	// caller keeps a useful bounded response. A member's Error is deliberately NOT
621	// trimmable: clearing it makes a member whose retrieval failed serialize as
622	// {"results": []}, byte-identical to a healthy member with no matches, and the
623	// generic response_truncated marker does not say a failure was suppressed.
624	// Ranked rows are the cheap thing to drop; a member's failure is not.
625	func trimWorkspaceExtrasOnce(groups []workspaceRetrieveResult) bool {
626		for i := len(groups) - 1; i >= 0; i-- {
627			switch {
628			case len(groups[i].AbstractPreviews) > 0:
629				groups[i].AbstractPreviews = groups[i].AbstractPreviews[:len(groups[i].AbstractPreviews)-1]
630				groups[i].AbstractPreviewsTruncated = true
631				return true
632			case groups[i].Freshness.Detail != "":
633				groups[i].Freshness.Detail = ""
634				return true
635			case groups[i].Freshness.ContractDetail != "":
636				groups[i].Freshness.ContractDetail = ""
637				return true
638			}
639		}
640		return false
641	}
