654	// applyWorkspaceTrimSteps rebuilds the trim state after `steps` steps of the
655	// deterministic sequence shared by both workspace surfaces: optional extras
656	// first, then one kept row at a time, then whole tail groups.
657	func applyWorkspaceTrimSteps(pristine []workspaceRetrieveResult, extrasSteps, total, steps int) (groups []workspaceRetrieveResult, keep int) {
658		gs := cloneWorkspaceRetrieveGroups(pristine)
659		for i := 0; i < min(steps, extrasSteps); i++ {
660			trimWorkspaceExtrasOnce(gs)
661		}
662		rowDrops := min(max(steps-extrasSteps, 0), total)
663		groupDrops := max(steps-extrasSteps-total, 0)
664		return gs[:len(gs)-groupDrops], total - rowDrops
665	}
